sources.scan/count.hlsl:
ByteAddressBuffer active_indices:register(t5,space0);
#include "common.hlsli"
ByteAddressBuffer lines:register(t1,space0);
ByteAddressBuffer path_records:register(t2,space0);
RWByteAddressBuffer backdrops:register(u3,space0);
RWByteAddressBuffer segment_tile_counts:register(u4,space0);
#include "geometry.hlsli"

[numthreads(SCAN_CHUNK_SIZE,1,1)]
void scan_count(uint3 id:SV_DispatchThreadID) {
    if(id.x>=config.line_count) return;
    ScanTraversal scan;
    if(!scan_geometry(dispatched_index(id.x,config.line_base),scan)) return;
    int delta=1;if(scan.down) delta=-1;
    uint ignored;
    for(int y=scan.ymin;y<scan.ymax;y++) {
        uint local=uint((y-int(scan.bbox.y))*int(scan.bbox.z-scan.bbox.x));
        backdrops.InterlockedAdd((scan.data_offset+local)*4u,asuint(delta),ignored);
    }
    float last_z=floor(scan.a*(float(scan.imin)-1.0)+scan.b);
    for(uint i=scan.imin;i<scan.imax;i++) {
        float z=floor(scan.a*float(i)+scan.b);
        int2 tile=scan_tile(scan,i,z);
        if(scan_tile_inside(scan,tile)) {
            bool top=last_z==z;
            if(i==0u) top=abs(scan.y0-scan.points.y*(1.0/float(SCAN_TILE_SIZE)))<=SCAN_EPSILON;
            if(top && tile.x+1<int(scan.bbox.z)) {
                int x=max(tile.x+1,int(scan.bbox.x));
                uint local=uint((tile.y-int(scan.bbox.y))*int(scan.bbox.z-scan.bbox.x)+x-int(scan.bbox.x));
                backdrops.InterlockedAdd((scan.data_offset+local)*4u,asuint(delta),ignored);
            }
            segment_tile_counts.InterlockedAdd(scan_tile_offset(scan,tile)*4u,1u,ignored);
        }
        last_z=z;
    }
}

sources.scan/geometry.hlsli:
// Shared DDA traversal for count and emit; arithmetic order follows the renderer
// geometry contract. Top-touch tolerance and tile snapping are distinct policies.
static const float SCAN_EPSILON=1.0e-6;
static const float TOP_TOUCH_EPSILON=1.0e-12;
static const float TILE_CLIP_NUDGE=1.0e-3;

struct ScanTraversal {
    uint4 bbox;
    uint data_offset;
    float4 points;
    bool down;
    uint count;
    float a,b,sign,x0,y0;
    uint imin,imax;
    int ymin,ymax;
};
bool is_tile_boundary_y(float value) {return abs(value-floor(value))<=TOP_TOUCH_EPSILON;}
int ceil_tile_boundary_y(float value) {if(is_tile_boundary_y(value)) return int(floor(value));return int(ceil(value));}
uint span(float a,float b) {float hi=ceil(a);if(b>a) hi=ceil(b);float lo=floor(a);if(b<a) lo=floor(b);float value=hi-lo;if(value<1.0) value=1.0;return uint(value);}

bool scan_geometry(uint line_index,out ScanTraversal scan) {
    scan=(ScanTraversal)0;
    uint line_base=line_index*SCAN_LINE_STRIDE;
    uint path_id=lines.Load(line_base);
    uint path_bytes;path_records.GetDimensions(path_bytes);
    if(path_id>=path_bytes/SCAN_PATH_RECORD_STRIDE) return false;
    uint path_base=path_id*SCAN_PATH_RECORD_STRIDE;
    scan.bbox=path_records.Load4(path_base+SCAN_PATH_BBOX);
    scan.data_offset=path_records.Load(path_base+SCAN_PATH_DATA_OFFSET);
    if(scan.bbox.z-scan.bbox.x==0u || scan.bbox.y>=scan.bbox.w) return false;
    float4 matrix=asfloat(path_records.Load4(path_base+SCAN_PATH_TRANSFORM));
    float2 translation=asfloat(path_records.Load2(path_base+SCAN_PATH_TRANSFORM+16u));
    float2 local0=asfloat(lines.Load2(line_base+SCAN_LINE_P0));
    float2 local1=asfloat(lines.Load2(line_base+SCAN_LINE_P1));
    float2 p0=float2(matrix.x*local0.x+matrix.z*local0.y+translation.x,matrix.y*local0.x+matrix.w*local0.y+translation.y);
    float2 p1=float2(matrix.x*local1.x+matrix.z*local1.y+translation.x,matrix.y*local1.x+matrix.w*local1.y+translation.y);
    scan.down=p1.y>=p0.y;
    scan.points=float4(p0,p1);
    if(!scan.down) scan.points=float4(p1,p0);
    float tile_scale=1.0/float(SCAN_TILE_SIZE);
    float4 s=scan.points*tile_scale;
    uint count_x=span(s.x,s.z)-1u;
    scan.count=count_x+span(s.y,s.w);
    float dx=abs(s.z-s.x);
    float dy=s.w-s.y;
    if(dx+dy==0.0 || (dy==0.0 && floor(s.y)==s.y)) return false;
    float reciprocal=1.0/(dx+dy);
    scan.a=dx*reciprocal;
    bool positive=s.z>=s.x;
    scan.sign=-1.0;if(positive) scan.sign=1.0;
    float xt0=floor(s.x*scan.sign);
    float c=s.x*scan.sign-xt0;
    scan.y0=floor(s.y);
    float ytop=scan.y0+1.0;if(s.y==s.w) ytop=ceil(s.y);
    scan.b=min((dy*c+dx*(ytop-s.y))*reciprocal,0.99999994);
