static const float TILE_CLIP_NUDGE=1.0e-3;

struct ScanTraversal {
    uint4 bbox;
    uint data_offset;
    float4 points;
    bool down;
    uint count;
    float a,b,sign,x0,y0;
    uint imin,imax;
    int ymin,ymax;
